"use strict";(globalThis.webpackChunkdocs_site=globalThis.webpackChunkdocs_site||[]).push([[3568],{4857(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/GradCore-Tensor/docs/Intro","label":"Introduction","docId":"Intro","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/Getting Started","label":"Getting Started","docId":"Getting Started","unlisted":false},{"type":"category","label":"Tutorials","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tutorials/tutorial-1-california-housing","label":"Tutorial 1: California Housing Regression","docId":"tutorials/tutorial-1-california-housing","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tutorials/tutorial-2-mnist","label":"Tutorial 2: MNIST Digit Classification","docId":"tutorials/tutorial-2-mnist","unlisted":false}],"href":"/GradCore-Tensor/docs/category/tutorials"},{"type":"category","label":"nn Module","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/","label":"nn Module Overview","docId":"nn_module/index","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/nn-to-tensor-flow","label":"High-Level to Low-Level Flow","docId":"nn_module/nn-to-tensor-flow","unlisted":false},{"type":"category","label":"Core","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/core/module","label":"Module","docId":"nn_module/core/module","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/core/sequential","label":"Sequential","docId":"nn_module/core/sequential","unlisted":false}],"href":"/GradCore-Tensor/docs/category/core"},{"type":"category","label":"Layers","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/layers/linear","label":"Linear","docId":"nn_module/layers/linear","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/layers/activations","label":"Activation Layers","docId":"nn_module/layers/activations","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/layers/batchnorm","label":"BatchNorm","docId":"nn_module/layers/batchnorm","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/layers/dropout","label":"Dropout","docId":"nn_module/layers/dropout","unlisted":false}],"href":"/GradCore-Tensor/docs/category/layers"},{"type":"category","label":"Losses","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/losses/overview","label":"Loss Functions","docId":"nn_module/losses/overview","unlisted":false}],"href":"/GradCore-Tensor/docs/category/losses"},{"type":"category","label":"Data","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/data/dataset","label":"Dataset","docId":"nn_module/data/dataset","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/data/dataloader","label":"DataLoader","docId":"nn_module/data/dataloader","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/data/csv_loader","label":"CSVLoader","docId":"nn_module/data/csv_loader","unlisted":false}],"href":"/GradCore-Tensor/docs/category/data"},{"type":"category","label":"Training","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/training/trainer","label":"Trainer","docId":"nn_module/training/trainer","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/training/training_stats","label":"TrainingStats","docId":"nn_module/training/training_stats","unlisted":false}],"href":"/GradCore-Tensor/docs/category/training"},{"type":"category","label":"Models","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/models/model","label":"Model","docId":"nn_module/models/model","unlisted":false}],"href":"/GradCore-Tensor/docs/category/models"},{"type":"category","label":"Utils","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/utils/initialization","label":"Initialization","docId":"nn_module/utils/initialization","unlisted":false}],"href":"/GradCore-Tensor/docs/category/utils"}],"href":"/GradCore-Tensor/docs/category/nn-module"},{"type":"category","label":"Optimizers","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/optim_module/overview","label":"Optimizer Overview","docId":"optim_module/overview","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/optim_module/sdg","label":"SGD","docId":"optim_module/sdg","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/optim_module/adam","label":"Adam","docId":"optim_module/adam","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/optim_module/adamw","label":"AdamW","docId":"optim_module/adamw","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/optim_module/rmsprop","label":"RMSprop","docId":"optim_module/rmsprop","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/optim_module/adagrad","label":"Adagrad","docId":"optim_module/adagrad","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/optim_module/lbfgs","label":"L-BFGS","docId":"optim_module/lbfgs","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/optim_module/optim_utils","label":"Optimizer Utilities","docId":"optim_module/optim_utils","unlisted":false}],"href":"/GradCore-Tensor/docs/category/optimizers"},{"type":"category","label":"Autograd","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/autograd_module/","label":"Autograd Overview","docId":"autograd_module/index","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/autograd_module/variable_and_graph","label":"Variables & the Graph","docId":"autograd_module/variable_and_graph","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/autograd_module/arithmetic","label":"Arithmetic Operations","docId":"autograd_module/arithmetic","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/autograd_module/activations","label":"Activation Operations","docId":"autograd_module/activations","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/autograd_module/losses","label":"Loss Operations","docId":"autograd_module/losses","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/autograd_module/autograd-integration","label":"Tensors in the Autograd Engine","docId":"autograd_module/autograd-integration","unlisted":false}],"href":"/GradCore-Tensor/docs/category/autograd"},{"type":"category","label":"Tensor Module","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/","label":"Tensor Module Overview","docId":"tensor_module/index","unlisted":false},{"type":"category","label":"Memory","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/memory/arena","label":"Arena Allocator","docId":"tensor_module/memory/arena","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/memory/platform","label":"Platform Layer","docId":"tensor_module/memory/platform","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/memory/prng","label":"PRNG","docId":"tensor_module/memory/prng","unlisted":false}],"href":"/GradCore-Tensor/docs/category/memory"},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/tensor-basics","label":"Tensor Basics","docId":"tensor_module/tensor-basics","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/tensor-views","label":"Tensor Views","docId":"tensor_module/tensor-views","unlisted":false},{"type":"category","label":"Arithmetic","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/arithmetic/overview","label":"Arithmetic Operations","docId":"tensor_module/arithmetic/overview","unlisted":false}],"href":"/GradCore-Tensor/docs/category/arithmetic"},{"type":"category","label":"Activations","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/activations/overview","label":"Activation Functions","docId":"tensor_module/activations/overview","unlisted":false}],"href":"/GradCore-Tensor/docs/category/activations"},{"type":"category","label":"Loss Functions","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/loss_functions/overview","label":"Loss Functions","docId":"tensor_module/loss_functions/overview","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/loss_functions/reduction-modes","label":"Reduction Modes","docId":"tensor_module/loss_functions/reduction-modes","unlisted":false}],"href":"/GradCore-Tensor/docs/category/loss-functions"}],"href":"/GradCore-Tensor/docs/category/tensor-module"}]},"docs":{"autograd_module/activations":{"id":"autograd_module/activations","title":"Activation Operations","description":"Every activation function in GradCore-Tensor has an autograd-layer wrapper. Each wrapper computes the activation in the forward pass, saves whatever tensors its backward function needs, and registers a backwardfn that calls the corresponding tensor*_grad function.","sidebar":"tutorialSidebar"},"autograd_module/arithmetic":{"id":"autograd_module/arithmetic","title":"Arithmetic Operations","description":"These are the differentiable arithmetic operations in the autograd layer. Each one calls the corresponding tensor* function for the forward computation and registers a backwardfn that computes the local gradient and accumulates it into parent grad tensors.","sidebar":"tutorialSidebar"},"autograd_module/autograd-integration":{"id":"autograd_module/autograd-integration","title":"Tensors in the Autograd Engine","description":"The tensor module provides the data. The autograd engine provides the memory of what you did with that data \u2014 so it can run the chain rule backwards. Here\'s how the two connect.","sidebar":"tutorialSidebar"},"autograd_module/index":{"id":"autograd_module/index","title":"Autograd Overview","description":"The autograd module is the machinery that makes training possible. Every call to autograd: it computes the output value (the forward pass), and it records a backward function that knows how to compute the gradient of that output with respect to its inputs. When you call autograd::backward(arena, loss), GradCore-Tensor replays those recorded functions in reverse to propagate gradients all the way back to the leaf parameters.","sidebar":"tutorialSidebar"},"autograd_module/losses":{"id":"autograd_module/losses","title":"Loss Operations","description":"The autograd loss functions are differentiable wrappers around the tensor-level loss functions. Each one computes the scalar loss in the forward pass, saves the tensors needed for the gradient, and registers a backward_fn that computes the gradient of the loss with respect to the model\'s predictions and accumulates it into the prediction\'s grad tensor.","sidebar":"tutorialSidebar"},"autograd_module/variable_and_graph":{"id":"autograd_module/variable_and_graph","title":"Variables & the Graph","description":"This page covers the two foundational functions of the autograd engine: create_leaf, which wraps a raw tensor into a graph-trackable Variable, and backward, which traverses the computation graph in reverse and accumulates gradients. Everything else in the autograd module builds on these two.","sidebar":"tutorialSidebar"},"Getting Started":{"id":"Getting Started","title":"Getting Started","description":"Getting Started","sidebar":"tutorialSidebar"},"Intro":{"id":"Intro","title":"Introduction","description":"GradCore-Tensor is a compact, high-performance C++ library for building, training, and running neural networks with an API inspired by PyTorch. It provides a clear, object-oriented implementation of tensors, an autograd engine, neural network building blocks, optimizers, and a lightweight data pipeline \u2014 all implemented from first principles so you can read, understand, and extend every part of the stack.","sidebar":"tutorialSidebar"},"nn_module/core/module":{"id":"nn_module/core/module","title":"Module","description":"Module is the abstract base class for every layer, activation, loss, and container in GradCore-Tensor. If you want to write a custom layer, you subclass Module. If you want to understand how a layer works internally, you understand Module first.","sidebar":"tutorialSidebar"},"nn_module/core/sequential":{"id":"nn_module/core/sequential","title":"Sequential","description":"Sequential is a Module that holds an ordered list of child modules and runs them one after another during forward(). The output of layer N is fed directly as input to layer N+1. That\'s it. Simple, composable, and the backbone of every model in GradCore-Tensor.","sidebar":"tutorialSidebar"},"nn_module/data/csv_loader":{"id":"nn_module/data/csv_loader","title":"CSVLoader","description":"CSVLoader is a static utility class for loading, parsing, and preprocessing tabular data from CSV files. It handles the entire pipeline from raw file to training-ready vectors \u2014 no external libraries, no Python dependency, no nonsense.","sidebar":"tutorialSidebar"},"nn_module/data/dataloader":{"id":"nn_module/data/dataloader","title":"DataLoader","description":"DataLoader slices a Dataset into mini-batches, optionally shuffles the sample order at the start of each epoch, and hands them to the training loop one batch at a time.","sidebar":"tutorialSidebar"},"nn_module/data/dataset":{"id":"nn_module/data/dataset","title":"Dataset","description":"Dataset is a thin wrapper that takes a block of float data (e.g. your training features or labels), stores it on the permanent arena, and exposes a shape-aware interface for DataLoader to batch from.","sidebar":"tutorialSidebar"},"nn_module/index":{"id":"nn_module/index","title":"nn Module Overview","description":"The nn module is the primary interface for building, training, and running neural networks in GradCore-Tensor. If the Tensor Module is the engine room, nn is the bridge \u2014 you issue commands here, and the lower layers handle all the mechanics.","sidebar":"tutorialSidebar"},"nn_module/layers/activations":{"id":"nn_module/layers/activations","title":"Activation Layers","description":"Activation layers are thin nn::* activation functions. They hold no parameters and no state \u2014 their only job is to sit in a Sequential and call the right autograd op when forward() is invoked.","sidebar":"tutorialSidebar"},"nn_module/layers/batchnorm":{"id":"nn_module/layers/batchnorm","title":"BatchNorm","description":"Batch Normalisation normalises a layer\'s inputs across the batch dimension, then rescales and shifts with learned parameters. The result is faster training, reduced sensitivity to initialisation, and a mild regularisation effect \u2014 which is a very good return on investment for two extra tensors.","sidebar":"tutorialSidebar"},"nn_module/layers/dropout":{"id":"nn_module/layers/dropout","title":"Dropout","description":"Dropout randomly zeroes out a fraction of activations during training. Each element is independently set to zero with probability p, and the surviving elements are scaled up by 1/(1-p) to keep the expected sum the same. During evaluation, dropout is a complete no-op \u2014 every neuron is active.","sidebar":"tutorialSidebar"},"nn_module/layers/linear":{"id":"nn_module/layers/linear","title":"Linear","description":"The fully-connected layer. Takes an input of shape [batch, infeatures], multiplies by a weight matrix, optionally adds a bias, and produces output of shape [batch, outfeatures].","sidebar":"tutorialSidebar"},"nn_module/losses/overview":{"id":"nn_module/losses/overview","title":"Loss Functions","description":"The nn loss classes are the user-facing wrappers over the tensor-level tensor*loss functions. They inherit from LossFunction, hold a Reduction mode, and expose a single forward() method. They also work as callables via operator().","sidebar":"tutorialSidebar"},"nn_module/models/model":{"id":"nn_module/models/model","title":"Model","description":"Model is the top-level object you interact with when building and training networks in GradCore-Tensor. It owns a Sequential container, wires together an optimizer and loss function, and exposes a Keras-style interface: compile then train then evaluate.","sidebar":"tutorialSidebar"},"nn_module/nn-to-tensor-flow":{"id":"nn_module/nn-to-tensor-flow","title":"High-Level to Low-Level Flow","description":"GradCore-Tensor follows a clean layered architecture. This design makes the library easy to use at a high level while remaining fully transparent and educational at lower levels.","sidebar":"tutorialSidebar"},"nn_module/training/trainer":{"id":"nn_module/training/trainer","title":"Trainer","description":"Trainer is the training loop engine. It owns no model weights \u2014 it receives a Module*, an optimizer, a loss function, and a graph arena, then runs the forward \u2192 loss \u2192 backward \u2192 step cycle for as many epochs as you ask for.","sidebar":"tutorialSidebar"},"nn_module/training/training_stats":{"id":"nn_module/training/training_stats","title":"TrainingStats","description":"TrainingStats is a plain data struct returned by Trainer::fit_dataloader at the end of a training run. It gives you a record of how the loss evolved over every epoch, plus a few headline numbers.","sidebar":"tutorialSidebar"},"nn_module/utils/initialization":{"id":"nn_module/utils/initialization","title":"Initialization","description":"Good weight initialisation is not optional \u2014 initialise too small and gradients vanish, too large and they explode. The functions in nn::init give you the standard schemes that the deep learning literature has converged on over the past decade.","sidebar":"tutorialSidebar"},"optim_module/adagrad":{"id":"optim_module/adagrad","title":"Adagrad","description":"Adagrad (Adaptive Gradient Algorithm) accumulates the sum of all squared gradients seen so far and divides the current gradient by its square root. Parameters that receive large gradients frequently get progressively smaller effective learning rates; parameters with sparse, infrequent gradients retain a larger effective rate. This makes Adagrad especially well-suited for tasks with naturally sparse gradient signals.","sidebar":"tutorialSidebar"},"optim_module/adam":{"id":"optim_module/adam","title":"Adam","description":"Adam (Adaptive Moment Estimation) maintains a running estimate of the first moment (mean) and second moment (uncentred variance) of the gradients, using them to scale the learning rate individually for each parameter. The result is an optimizer that adapts to the local curvature of the loss landscape and typically requires far less tuning than SGD.","sidebar":"tutorialSidebar"},"optim_module/adamw":{"id":"optim_module/adamw","title":"AdamW","description":"AdamW is Adam with decoupled weight decay. The key insight (Loshchilov & Hutter, 2019) is that adding L2 regularisation to the loss and then running Adam is not the same as applying weight decay directly to the weights. Standard Adam scales the weight decay term by the adaptive learning rate, making its effective magnitude inconsistent across parameters and training steps. AdamW fixes this by applying weight decay as a direct multiplicative shrinkage of the weight, completely separate from the gradient update.","sidebar":"tutorialSidebar"},"optim_module/lbfgs":{"id":"optim_module/lbfgs","title":"L-BFGS","description":"L-BFGS (Limited-memory Broyden\u2013Fletcher\u2013Goldfarb\u2013Shanno) is a quasi-Newton optimizer. Rather than following the gradient directly, it uses a history of past gradient changes to build an approximation of the inverse Hessian \u2014 the curvature of the loss landscape \u2014 and uses that approximation to compute a better search direction. The result is much faster convergence per gradient evaluation than any first-order method, at the cost of requiring a closure (a function that re-evaluates the loss and its gradients on demand for the line search) and being fundamentally incompatible with mini-batch stochastic training.","sidebar":"tutorialSidebar"},"optim_module/optim_utils":{"id":"optim_module/optim_utils","title":"Optimizer Utilities","description":"optim_utils.hpp is a header-only collection of inline helper functions used internally by the L-BFGS optimizer to flatten parameter and gradient vectors into a single 1D tensor, and to restore parameters from that flat representation. They are also useful when implementing custom second-order optimizers.","sidebar":"tutorialSidebar"},"optim_module/overview":{"id":"optim_module/overview","title":"Optimizer Overview","description":"Optimizers are responsible for updating model parameters after every backward pass. They read the gradient that autograd::data. Everything else in the training loop \u2014 the forward pass, the loss, the backward pass \u2014 exists to produce those gradients. The optimizer is where gradients become learning.","sidebar":"tutorialSidebar"},"optim_module/rmsprop":{"id":"optim_module/rmsprop","title":"RMSprop","description":"RMSprop (Root Mean Square Propagation) divides the learning rate by a running average of recent squared gradient magnitudes. This normalises the effective step size across parameters \u2014 parameters with historically large gradients get smaller steps, and parameters with small gradients get larger ones. Unlike Adam, RMSprop does not maintain a first moment estimate, making it lighter on memory and slightly simpler.","sidebar":"tutorialSidebar"},"optim_module/sdg":{"id":"optim_module/sdg","title":"SGD","description":"Stochastic Gradient Descent. The oldest optimizer, still competitive, and the easiest to reason about. Every weight moves directly opposite its gradient, scaled by the learning rate.","sidebar":"tutorialSidebar"},"tensor_module/activations/overview":{"id":"tensor_module/activations/overview","title":"Activation Functions","description":"Activation functions introduce non-linearity into your network. Without them, a 47-layer neural network would have the expressive power of a single matrix multiply \u2014 and we\'d all be out of a hobby.","sidebar":"tutorialSidebar"},"tensor_module/arithmetic/overview":{"id":"tensor_module/arithmetic/overview","title":"Arithmetic Operations","description":"These are the low-level tensor math functions. Every layer in GradCore-Tensor ultimately calls one or more of these. They all follow the same conventions:","sidebar":"tutorialSidebar"},"tensor_module/index":{"id":"tensor_module/index","title":"Tensor Module Overview","description":"Welcome to the nerve centre of GradCore-Tensor. Everything \u2014 training, inference, backprop, your optimizer quietly panicking about learning rates \u2014 ultimately comes down to operations on Tensor objects. This section documents every corner of the tensor module so you know exactly what\'s happening under the hood.","sidebar":"tutorialSidebar"},"tensor_module/loss_functions/overview":{"id":"tensor_module/loss_functions/overview","title":"Loss Functions","description":"A loss function measures how wrong your model is. Training is the process of making it less wrong, one gradient at a time. Choosing the right loss function is not optional \u2014 using MSE for a classification problem is like using a ruler to measure temperature.","sidebar":"tutorialSidebar"},"tensor_module/loss_functions/reduction-modes":{"id":"tensor_module/loss_functions/reduction-modes","title":"Reduction Modes","description":"Reduction modes control whether a loss function returns a per-element tensor or collapses to a scalar. Every loss function in GradCore-Tensor accepts a Reduction argument.","sidebar":"tutorialSidebar"},"tensor_module/memory/arena":{"id":"tensor_module/memory/arena","title":"Arena Allocator","description":"The Arena is GradCore-Tensor\'s memory backbone. If you\'ve ever watched a neural network training session grind to a halt because malloc decided it was a great time to coalesce free blocks, you\'ll appreciate what an arena allocator does for you: it doesn\'t bother with any of that.","sidebar":"tutorialSidebar"},"tensor_module/memory/platform":{"id":"tensor_module/memory/platform","title":"Platform Layer","description":"platform.hpp is a thin wrapper around OS-level operations: virtual memory management and entropy generation. All the gritty mmap/munmap/mprotect calls live here so the rest of the codebase stays clean and portable (in theory \u2014 in practice it\'s Linux only, as the Introduction honestly admits).","sidebar":"tutorialSidebar"},"tensor_module/memory/prng":{"id":"tensor_module/memory/prng","title":"PRNG","description":"GradCore-Tensor uses a PCG (Permuted Congruential Generator) for all random number generation. PCG is fast, has excellent statistical properties, and produces 32 bits of randomness per step \u2014 which is exactly what you need for weight initialisation and data shuffling, and absolutely overkill for anything that doesn\'t need cryptographic security (which is everything in a neural network training loop).","sidebar":"tutorialSidebar"},"tensor_module/tensor-basics":{"id":"tensor_module/tensor-basics","title":"Tensor Basics","description":"The Tensor struct is the central data structure in GradCore-Tensor. It describes a multi-dimensional array of float values and knows how to index into them correctly, whether the data is contiguous in memory or is a strided view of something else.","sidebar":"tutorialSidebar"},"tensor_module/tensor-views":{"id":"tensor_module/tensor-views","title":"Tensor Views","description":"Views are tensors that share memory with another tensor. Changing the data through a view changes the original, and vice versa \u2014 because they\'re the same bytes, just described differently.","sidebar":"tutorialSidebar"},"tutorials/tutorial-1-california-housing":{"id":"tutorials/tutorial-1-california-housing","title":"Tutorial 1: California Housing Regression","description":"This tutorial walks through the California Housing dataset regression example end-to-end \u2014 from loading CSV data to running inference on unseen samples. By the end you will understand how CSVLoader, nn::Model, and the training loop fit together.","sidebar":"tutorialSidebar"},"tutorials/tutorial-2-mnist":{"id":"tutorials/tutorial-2-mnist","title":"Tutorial 2: MNIST Digit Classification","description":"This tutorial covers multi-class image classification using the MNIST handwritten digit dataset. You will learn how to set up batched loading with DataLoader, build a classifier, train with CrossEntropyLoss, evaluate test accuracy, and run per-sample inference with a visual terminal display.","sidebar":"tutorialSidebar"}}}}')}}]);